#---------------------------------------------------------
#--this file is used to visualize the experiment results
#--generated by the ExperimentPart.
#---------------------------------------------------------

import os
import torch
import numpy as np
import matplotlib.pyplot as plt
from matplotlib.ticker import MultipleLocator

from sklearn.manifold import TSNE

from sklearn.metrics import (
    confusion_matrix,
    ConfusionMatrixDisplay
)


class Visualization:

    def __init__(
        self,
        data_loader,
        publication_output=False
    ):

        #--store the experiment data loader.
        self.data_loader = data_loader

        #--store the publication output option.
        self.publication_output = publication_output


    #--get the best run of the experiment.
    def _get_best_run(self, run_level_view):

        best_run = None

        for run_info in run_level_view:

            if best_run is None:
                best_run = run_info
                continue

            #--compare test accuracy.
            if run_info["test_accuracy"] > best_run["test_accuracy"]:
                best_run = run_info
                continue

            if run_info["test_accuracy"] < best_run["test_accuracy"]:
                continue

            #--compare test loss when test accuracy is equal.
            if run_info["test_loss"] < best_run["test_loss"]:
                best_run = run_info
                continue

            if run_info["test_loss"] > best_run["test_loss"]:
                continue

            #--compare selected epoch train time when
            #--test accuracy and test loss are equal.
            if (
                run_info["selected_epoch_train_time"]
                < best_run["selected_epoch_train_time"]
            ):
                best_run = run_info
                continue

            if (
                run_info["selected_epoch_train_time"]
                > best_run["selected_epoch_train_time"]
            ):
                continue

            #--if all criteria are equal, keep the first run.
            #--Therefore, no action is required here.

        return best_run


    #--get the worst run of the experiment.
    def _get_worst_run(self, run_level_view):

        worst_run = None

        for run_info in run_level_view:

            if worst_run is None:
                worst_run = run_info
                continue

            #--compare test accuracy.
            if run_info["test_accuracy"] < worst_run["test_accuracy"]:
                worst_run = run_info
                continue

            if run_info["test_accuracy"] > worst_run["test_accuracy"]:
                continue

            #--compare test loss when test accuracy is equal.
            if run_info["test_loss"] > worst_run["test_loss"]:
                worst_run = run_info
                continue

            if run_info["test_loss"] < worst_run["test_loss"]:
                continue

            #--compare selected epoch train time when
            #--test accuracy and test loss are equal.
            if (
                run_info["selected_epoch_train_time"]
                > worst_run["selected_epoch_train_time"]
            ):
                worst_run = run_info
                continue

            if (
                run_info["selected_epoch_train_time"]
                < worst_run["selected_epoch_train_time"]
            ):
                continue

            #--if all criteria are equal, keep the first run.
            #--Therefore, no action is required here.

        return worst_run


    #--get features for poltting from the best run.
    def _get_features(
        self,
        best_run,
        feature_layer
    ):
        #--get the feature file path.
        features_path = best_run["features_path"]

        features_file_path = os.path.join(
            self.data_loader.experiment_data_path,
            features_path
        )

        #--load the feature data.
        features = torch.load(
            features_file_path,
            weights_only=False
        )

        #--get the specified feature layer.
        feature_data = features[feature_layer]["data"]

        return feature_data


    #--prepare the feature data for t-SNE.
    #--keep the sample dimension and flatten all remaining dimensions.
    def _prepare_features(
        self,
        feature_data
    ):

        #--flatten all dimensions except the sample dimension.
        feature_data = feature_data.reshape(
            feature_data.shape[0],
            -1
        )

        #--convert the feature data to NumPy array.
        feature_data = feature_data.detach().cpu().numpy()

        return feature_data


    #--plot the t-SNE visualization of model features.
    def _plot_model_features(
        self,
        best_run
    ):

        #--create the output directory.
        feature_output_dir = os.path.join(
            self.data_loader.experiment_path,
            "Features_plots"
        )

        os.makedirs(
            feature_output_dir,
            exist_ok=True
        )

        #--get the labels of the best run.
        y_true = np.asarray(
            best_run["y_true"]
        )

        #--plot every selected feature layer.
        for feature_layer in self.data_loader.plot_feature_layers:

            #--get the feature data of the specified layer.
            feature_data = self._get_features(
                best_run,
                feature_layer
            )

            #--prepare the feature data for t-SNE.
            feature_data = self._prepare_features(
                feature_data
            )

            #--validate the consistency between
            #--feature samples and test labels.
            if feature_data.shape[0] != len(y_true):
                raise ValueError(
                    "The number of feature samples does not "
                    "match the number of test labels."
                )

            #--perform t-SNE.
            tsne = TSNE(
                n_components=2,
                random_state=42
            )

            feature_2d = tsne.fit_transform(
                feature_data
            )

            #--create the figure.
            fig, ax = plt.subplots(
                figsize=(8, 6)
            )

            #--get the unique labels.
            unique_labels = np.unique(
                y_true
            )

            #--plot every class.
            for label in unique_labels:

                mask = (
                    y_true == label
                )

                ax.scatter(
                    feature_2d[mask, 0],
                    feature_2d[mask, 1],
                    label=str(label),
                    alpha=0.7
                )

            ax.set_xlabel(
                "t-SNE 1"
            )

            ax.set_ylabel(
                "t-SNE 2"
            )

            ax.legend()

            ax.grid(
                True,
                linestyle="--",
                alpha=0.3
            )

            plt.tight_layout()

            #--build the output filename.
            output_filename = (
                f"{self.data_loader.experiment_name}_"
                f"{self.data_loader.experiment_id}_"
                f"{feature_layer}.png"
            )

            output_path = os.path.join(
                feature_output_dir,
                output_filename
            )

            #--save the figure.
            dpi = (
                600
                if self.publication_output
                else 300
            )

            plt.savefig(
                output_path,
                dpi=dpi,
                bbox_inches="tight"
            )

            #--save PDF for publication output.
            if self.publication_output:

                pdf_output_path = os.path.join(
                    feature_output_dir,
                    output_filename.replace(
                        ".png",
                        ".pdf"
                    )
                )

                plt.savefig(
                    pdf_output_path,
                    bbox_inches="tight"
                )

            plt.close(fig)


    #--plot box plots for the epoch-level experiment results.
    def _plot_boxplot(self, epoch_level_view):
 
        metric_info = {
        "train_accuracy": "Train Accuracy",
        "validation_accuracy": "Validation Accuracy",
        "train_loss": "Train Loss",
        "validation_loss": "Validation Loss"
    }

        # ---------------------------------------------------------
        # Experiment paths
        # ---------------------------------------------------------
        experiment_dir = os.path.join(
            self.data_loader.experiment_data_path,
            f"{self.data_loader.experiment_name}_"
            f"{self.data_loader.experiment_id}"
        )

        boxplot_dir = os.path.join(
            experiment_dir,
            "Box_plots"
        )

        os.makedirs(
            boxplot_dir,
            exist_ok=True
        )

        experiment_name = self.data_loader.experiment_name
        experiment_id = self.data_loader.experiment_id

        # ---------------------------------------------------------
        # Determine visualization interval
        # ---------------------------------------------------------
        max_epoch_num = max(
            epoch_info["epoch_num"]
            for epoch_info in epoch_level_view
        )

        if max_epoch_num <= 5:
            epoch_interval = 1
        else:
            epoch_interval = 5

        # ---------------------------------------------------------
        # Plot each metric
        # ---------------------------------------------------------
        for metric_name, metric_label in metric_info.items():

            epoch_numbers = []
            epoch_values = []
            epoch_medians = []

            # -----------------------------------------------------
            # Collect data
            # -----------------------------------------------------
            for epoch_info in epoch_level_view:

                epoch_num = epoch_info["epoch_num"]

                # Visualization sampling
                if max_epoch_num > 5:
                    if epoch_num % epoch_interval != 0:
                        continue

                values = []

                for run_info in epoch_info["runs"]:

                    if not run_info["is_exist"]:
                        continue

                    value = run_info[metric_name]

                    if value is None:
                        continue

                    values.append(value)

                # No valid data for this epoch
                if len(values) == 0:
                    continue

                epoch_numbers.append(epoch_num)
                epoch_values.append(values)

                # -------------------------------------------------
                # Median trend
                # -------------------------------------------------
                median_value = np.median(values)
                epoch_medians.append(median_value)

            # -----------------------------------------------------
            # No data available
            # -----------------------------------------------------
            if len(epoch_values) == 0:
                continue

            # -----------------------------------------------------
            # Determine trend color
            # -----------------------------------------------------
            if "train" in metric_name:
                trend_color = "#8B0D0D"
            else:
                trend_color = "#05268A"

            # -----------------------------------------------------
            # Outlier style
            # -----------------------------------------------------
            flierprops = dict(
                marker="o",
                markerfacecolor="none",
                markeredgecolor="black",
                markersize=3.5,
                linestyle="none"
            )

            # -----------------------------------------------------
            # Create figure
            # -----------------------------------------------------
            fig, ax = plt.subplots(
                figsize=(8, 5)
            )

            # -----------------------------------------------------
            # Boxplot
            # -----------------------------------------------------
            ax.boxplot(
                epoch_values,
                tick_labels=epoch_numbers,
                widths=0.165,
                patch_artist=False,

                boxprops=dict(
                    color="black",
                    linewidth=0.6
                ),

                whiskerprops=dict(
                    color="black",
                    linewidth=0.6
                ),

                capprops=dict(
                    color="black",
                    linewidth=0.6
                ),

                medianprops=dict(
                    color="black",
                    linewidth=0.6
                ),

                flierprops=flierprops
            )

            # -----------------------------------------------------
            # Median trend line
            # -----------------------------------------------------
            ax.plot(
                range(1, len(epoch_numbers) + 1),
                epoch_medians,
                color=trend_color,
                marker="o",
                linewidth=0.8,
                markersize=4.5,
                label="Median Trend"
            )

            # -----------------------------------------------------
            # Labels
            # -----------------------------------------------------
            ax.set_xlabel("Epoch")
            ax.set_ylabel(metric_label)

            # -----------------------------------------------------
            # Accuracy Y-axis
            # -----------------------------------------------------
            if "accuracy" in metric_name:

                data_min = min(
                    min(values)
                    for values in epoch_values
                )

                data_max = max(
                    max(values)
                    for values in epoch_values
                )

                data_range = data_max - data_min

                # -------------------------------------------------
                # Determine margin
                # -------------------------------------------------
                if data_range == 0:
                    margin = 0.01
                else:
                    margin = data_range * 0.10

                lower_limit = max(
                    0.0,
                    data_min - margin
                )

                upper_limit = min(
                    1.0,
                    data_max + margin
                )

                # -------------------------------------------------
                # Prevent excessively narrow axis
                # -------------------------------------------------
                if upper_limit - lower_limit < 0.02:

                    center = (
                        upper_limit +
                        lower_limit
                    ) / 2

                    lower_limit = max(
                        0.0,
                        center - 0.01
                    )

                    upper_limit = min(
                        1.0,
                        center + 0.01
                    )

                ax.set_ylim(
                    lower_limit,
                    upper_limit
                )

            # -----------------------------------------------------
            # Grid
            # -----------------------------------------------------
            ax.grid(
                axis="y",
                linestyle="--",
                alpha=0.5
            )

            # -----------------------------------------------------
            # Legend
            # -----------------------------------------------------
            ax.legend()

            # -----------------------------------------------------
            # Layout
            # -----------------------------------------------------
            fig.tight_layout()

            # -----------------------------------------------------
            # File name
            # -----------------------------------------------------
            file_name = (
                f"{experiment_name}_"
                f"{experiment_id}_"
                f"{metric_name}"
            )

            # -----------------------------------------------------
            # Save PNG
            # -----------------------------------------------------
            png_path = os.path.join(
                boxplot_dir,
                f"{file_name}.png"
            )

            if self.publication_output:
                png_dpi = 600
            else:
                png_dpi = 300

            fig.savefig(
                png_path,
                dpi=png_dpi,
                bbox_inches="tight"
            )

            # -----------------------------------------------------
            # Save PDF
            # -----------------------------------------------------
            if self.publication_output:

                pdf_path = os.path.join(
                    boxplot_dir,
                    f"{file_name}.pdf"
                )

                fig.savefig(
                    pdf_path,
                    format="pdf",
                    bbox_inches="tight"
                )

            # -----------------------------------------------------
            # Close figure
            # -----------------------------------------------------
            plt.close(fig)


    #--polt mean curve for the whole training and validation process.
    def _plot_mean_curve(self, epoch_level_view):

        experiment_dir = os.path.join(
            self.data_loader.experiment_data_path,
            f"{self.data_loader.experiment_name}_"
            f"{self.data_loader.experiment_id}"
        )

        mean_curve_dir = os.path.join(
            experiment_dir,
            "Mean_curves"
        )

        os.makedirs(
            mean_curve_dir,
            exist_ok=True
        )

        experiment_name = self.data_loader.experiment_name
        experiment_id = self.data_loader.experiment_id

        # Metrics
        metric_info = {
            "accuracy": {
                "train_key": "train_accuracy",
                "validation_key": "validation_accuracy",
                "ylabel": "Accuracy"
            },
            "loss": {
                "train_key": "train_loss",
                "validation_key": "validation_loss",
                "ylabel": "Loss"
            }
        }

        # Colors
        train_color = "#971414"
        validation_color = "#092063"

        # Calculate mean curves
        for metric_name, info in metric_info.items():

            epoch_numbers = []

            train_means = []
            validation_means = []

            for epoch_info in epoch_level_view:

                epoch_num = epoch_info["epoch_num"]

                train_values = []
                validation_values = []

                for run_info in epoch_info["runs"]:

                    if not run_info["is_exist"]:
                        continue

                    train_value = run_info[info["train_key"]]
                    validation_value = run_info[info["validation_key"]]

                    if train_value is not None:
                        train_values.append(train_value)

                    if validation_value is not None:
                        validation_values.append(validation_value)

                # Skip epoch if neither metric has valid data
                if (
                    len(train_values) == 0
                    and len(validation_values) == 0
                ):
                    continue

                epoch_numbers.append(epoch_num)

                # Mean training metric
                if len(train_values) > 0:
                    train_means.append(
                        np.mean(train_values)
                    )
                else:
                    train_means.append(
                        np.nan
                    )

                # Mean validation metric
                if len(validation_values) > 0:
                    validation_means.append(
                        np.mean(validation_values)
                    )
                else:
                    validation_means.append(
                        np.nan
                    )

            # No data available
            if len(epoch_numbers) == 0:
                continue

            # Create figure
            fig, ax = plt.subplots(
                figsize=(8, 5)
            )

            # Training curve
            ax.plot(
                epoch_numbers,
                train_means,
                color=train_color,
                linewidth=1.0,
                marker="o",
                markersize=3.5,
                label="Training"
            )

            # Validation curve
            ax.plot(
                epoch_numbers,
                validation_means,
                color=validation_color,
                linewidth=1.0,
                marker="^",
                markersize=3.5,
                label="Validation"
            )

            # Labels
            ax.set_xlabel("Epoch")
            ax.set_ylabel(info["ylabel"])

            # X-axis starts from zero
            ax.set_xlim(
                left=0
            )

            # Y-axis starts from zero
            ax.set_ylim(
                bottom=0
            )

            # Accuracy Y-axis
            if metric_name == "accuracy":

                ax.set_ylim(
                    0.0,
                    1.0
                )

                # Accuracy Y-axis: 0.1 interval
                ax.set_yticks(
                    np.arange(
                        0.0,
                        1.01,
                        0.1
                    )
                )

            # Grid
            ax.grid(
                axis="y",
                linestyle="--",
                alpha=0.5
            )

            # Legend
            ax.legend()

            # Layout
            fig.tight_layout()

            # File name
            file_name = (
                f"{experiment_name}_"
                f"{experiment_id}_"
                f"average_{metric_name}"
            )

            # Save PNG
            png_path = os.path.join(
                mean_curve_dir,
                f"{file_name}.png"
            )

            if self.publication_output:
                png_dpi = 600
            else:
                png_dpi = 300

            fig.savefig(
                png_path,
                dpi=png_dpi,
                bbox_inches="tight"
            )

            # Save PDF
            if self.publication_output:

                pdf_path = os.path.join(
                    mean_curve_dir,
                    f"{file_name}.pdf"
                )

                fig.savefig(
                    pdf_path,
                    format="pdf",
                    bbox_inches="tight"
                )

            # Close figure
            plt.close(fig)


    #--plot current confusion matrix
    def _plot_result_confusion_matrix(
        self,
        run_info,
        result_type
    ):

        #--get the test results.
        y_true = np.asarray(run_info["y_true"])
        y_pred = np.asarray(run_info["y_pred"])
        label_to_index = run_info["label_to_index"]

        #--get the class indices and corresponding labels.
        labels = sorted(label_to_index.values())

        index_to_label = {
            index: label
            for label, index in label_to_index.items()
        }

        display_labels = [
            index_to_label[index]
            for index in labels
        ]

        #--calculate the confusion matrix.
        cm = confusion_matrix(
            y_true,
            y_pred,
            labels=labels
        )

        #--normalize the confusion matrix by the true-label rows.
        row_sums = cm.sum(axis=1, keepdims=True)

        cm_percentage = np.zeros_like(
            cm,
            dtype=float
        )

        np.divide(
            cm,
            row_sums,
            out=cm_percentage,
            where=row_sums != 0
        )

        cm_percentage *= 100

        #--create the output directory.
        confusion_matrix_output_dir = os.path.join(
            self.data_loader.experiment_path,
            "Confusion_matrix"
        )

        os.makedirs(
            confusion_matrix_output_dir,
            exist_ok=True
        )

        #--create the confusion matrix display.
        display = ConfusionMatrixDisplay(
            confusion_matrix=cm_percentage,
            display_labels=display_labels
        )

        fig, ax = plt.subplots(
            figsize=(10, 8)
        )

        display.plot(
            ax=ax,
            values_format=".2f",
            cmap="Blues",
            colorbar=True
        )

        #--set axis labels.
        ax.set_xlabel("Predicted label")
        ax.set_ylabel("True label")

        #--rotate x-axis labels for readability.
        plt.setp(
            ax.get_xticklabels(),
            rotation=45,
            ha="right"
        )

        plt.tight_layout()

        #--build the output file name.
        output_file_name = (
            f"{self.data_loader.experiment_name}_"
            f"{self.data_loader.experiment_id}_"
            f"{result_type}"
        )

        output_file_path = os.path.join(
            confusion_matrix_output_dir,
            f"{output_file_name}.png"
        )

        #--save the normal-resolution figure.
        plt.savefig(
            output_file_path,
            dpi=300,
            bbox_inches="tight"
        )

        #--save publication-quality output.
        if self.publication_output:

            publication_output_file_path = os.path.join(
                confusion_matrix_output_dir,
                f"{output_file_name}.pdf"
            )

            plt.savefig(
                publication_output_file_path,
                dpi=600,
                bbox_inches="tight"
            )

        plt.close(fig)



    #--plot the best and worst confusion matrix.
    def plot_confusion_matrix(
        self,
        run_level_view
    ):

        #--get the best and worst runs.
        best_run = self._get_best_run(
            run_level_view
        )

        worst_run = self._get_worst_run(
            run_level_view
        )

        #--plot the best run confusion matrix.
        self._plot_result_confusion_matrix(
            best_run,
            "best"
        )

        #--plot the worst run confusion matrix.
        self._plot_result_confusion_matrix(
            worst_run,
            "worst"
        )



    #--run the complete visualization process.
    def run(
        self,
        epoch_level_view,
        run_level_view
    ):


        #--plot box plots.
        print(
            "[Visualization] Plotting box plots started."
        )

        self._plot_boxplot(
            epoch_level_view
        )

        print(
            "[Visualization] Plotting box plots completed."
        )


    
        #--plot mean curves.
        print(
            "[Visualization] Plotting mean curves started."
        )

        self._plot_mean_curve(
            epoch_level_view
        )

        print(
            "[Visualization] Plotting mean curves completed."
        )


   
        #--plot model features.
        print(
            "[Visualization] Plotting model features started."
        )

        best_run = self._get_best_run(
            run_level_view
        )

        self._plot_model_features(
            best_run
        )

        print(
            "[Visualization] Plotting model features completed."
        )

        #--plot confusion matrices.
        print(
            "[Visualization] Plotting confusion matrices started."
        )

        self.plot_confusion_matrix(
            run_level_view
        )

        print(
            "[Visualization] Plotting confusion matrices completed."
        )